SELECT 
FROM activity
WHERE status = 3
  AND start_time <= #{now}
  AND end_time > #{now}

  AND (name LIKE CONCAT('%', #{keyword}, '%')
       OR summary LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY start_time ASC, id ASC
LIMIT #{limit} OFFSET #{offset}

SELECT id
FROM activity
WHERE status = 2
  AND start_time <= #{now}
  AND end_time > #{now}
ORDER BY start_time ASC, id ASC
LIMIT #{limit}

SELECT id
FROM activity
WHERE status = 2
  AND end_time <= #{now}
ORDER BY end_time ASC, id ASC
LIMIT #{limit}

SELECT id
FROM activity
WHERE status = 3
  AND end_time <= #{now}
ORDER BY end_time ASC, id ASC
LIMIT #{limit}
